/* ================= Series 65 · second bank: exam-level questions and more facts (original, NASAA June 2023 outline) ================= */
/* ---- facts that fill outline gaps ---- */
F(5,1,"Components of GDP","Consumer spending + business investment + government spending + net exports (C + I + G + net exports).");
F(5,1,"The Federal Reserve's dual mandate","Maximum employment and stable prices.");
F(5,1,"Working capital","Current assets − current liabilities.");
F(5,1,"Earnings per share (EPS)","(Net income − preferred dividends) ÷ common shares outstanding.");
F(5,1,"Book value per share","(Total assets − total liabilities − preferred stock) ÷ common shares outstanding.");
F(5,1,"Balance of payments","The record of all money flows between a country and the rest of the world: the current account (trade) and the capital account.");
F(5,1,"Currency risk","The risk that a change in exchange rates lowers the dollar value of a foreign investment.");
F(5,1,"Real interest rate","The nominal interest rate minus inflation.");
F(5,1,"Coefficient of determination (R-squared)","How much of a portfolio's movement is explained by its benchmark. Low R-squared makes beta less meaningful.");
F(5,1,"Range","The difference between the highest and lowest values.");
F(5,2,"Treasury STRIPS","Zero-coupon securities made by separating the interest and principal of Treasury notes and bonds; taxed each year on accreted interest (phantom income).");
F(5,2,"GNMA versus FNMA and FHLMC","GNMA is backed by the full faith and credit of the U.S. government; Fannie Mae and Freddie Mac are government-sponsored but not directly backed.");
F(5,2,"Prepayment and extension risk","Mortgage-backed holders get money back early when rates fall (prepayment) and later than expected when rates rise (extension).");
F(5,2,"Mortgage bond, equipment trust and debenture","Mortgage bonds are secured by real property, equipment trust certificates by equipment; debentures are unsecured.");
F(5,2,"Sinking fund","Money an issuer sets aside to retire bonds before maturity; lowers default risk.");
F(5,2,"Money market fund","A mutual fund holding short-term debt; seeks a stable $1 NAV but is not FDIC insured.");
F(5,2,"Stock split and stock dividend","More shares at a lower price per share; the investor's total value and proportion do not change. Not taxable.");
F(5,2,"Rights versus warrants","Rights: short-term, issued to current shareholders, price below market. Warrants: long-term, price above market when issued.");
F(5,2,"Yield to call is lowest when","The bond trades at a premium and is likely to be called.");
F(5,2,"Variable annuity phases","Accumulation (accumulation units) and annuitization (fixed number of annuity units; payments vary with performance against the AIR).");
F(5,2,"Assumed interest rate (AIR)","If separate account returns beat the AIR, the next variable annuity payment rises; if they fall short, it drops.");
F(5,2,"Section 1035 exchange","A tax-free swap of one life insurance or annuity contract for another of the same or allowed kind.");
F(5,2,"Surrender charge","A fee for withdrawing from an annuity in its early years; it declines over time.");
F(5,2,"Death benefit of an annuity","Typically the greater of contract value or total premiums paid; gains are taxed to the beneficiary as ordinary income (no step-up).");
F(5,2,"Index fund versus actively managed fund","Index funds track a benchmark at low cost and low turnover, usually with fewer taxable distributions.");
F(5,2,"Long straddle","Buying a call and a put on the same stock at the same strike: profits from a large move either way.");
F(5,2,"Hedging with futures","A producer sells futures to lock in a price (short hedge); a user buys futures (long hedge).");
F(5,3,"Required minimum distributions: inherited IRAs","Most non-spouse beneficiaries must empty the account within 10 years; spouses, minor children, disabled or chronically ill heirs and those not more than 10 years younger are exceptions.");
F(5,3,"529 to Roth IRA rollover","Up to $35,000 lifetime from a 529 open at least 15 years to the beneficiary's Roth IRA, within the yearly Roth limit (SECURE 2.0).");
F(5,3,"Roth 401(k) RMDs","None for the owner since 2024 (SECURE 2.0).");
F(5,3,"60-day rollover rule","An indirect IRA rollover must be completed within 60 days; only one per 12 months. Direct trustee-to-trustee transfers have no limit.");
F(5,3,"Mandatory withholding on plan distributions","20% federal withholding when an employer plan pays the money to the participant instead of directly to an IRA.");
F(5,3,"Social Security full retirement age","67 for those born in 1960 or later. Claiming at 62 reduces benefits; delaying past full retirement age adds 8% a year until 70.");
F(5,3,"Kiddie tax","A child's unearned income above a yearly threshold is taxed at the parents' rate; applies to children under 19, or under 24 if full-time students.");
F(5,3,"Trust income tax brackets","Very compressed: a trust reaches the top 37% bracket at a small fraction of an individual's income.");
F(5,3,"C corporation tax rate","A flat 21% federal rate.");
F(5,3,"Dividends received deduction","A C corporation owning less than 20% of another domestic corporation can deduct 50% of the dividends it receives.");
F(5,3,"Federal estate tax exemption, 2026","$15 million per person, indexed for inflation after 2026 (One Big Beautiful Bill Act).");
F(5,3,"Uniform Prudent Investor Act","Judge investments as part of the whole portfolio, diversify, consider total return, allow delegation to agents; no type of investment is forbidden in itself.");
F(5,3,"Anchoring (behavioral finance)","Relying too much on one first number, such as a stock's purchase price.");
F(5,3,"Overconfidence and confirmation bias","Overrating one's own skill; seeking only information that supports a view already held.");
F(5,3,"Mental accounting","Treating money differently depending on where it came from or what it is labeled for.");
F(5,3,"Recency and herd behavior","Giving too much weight to recent events; following what others do.");
F(5,3,"Asset location","Putting tax-inefficient investments (taxable bonds, REITs) in tax-deferred accounts and tax-efficient ones in taxable accounts.");
F(5,3,"Contrarian strategy","Buying what is out of favor and selling what is popular.");
F(5,3,"Buy and hold","A passive approach of holding investments for the long term regardless of market swings.");
F(5,3,"Customer identification program (CIP)","Before opening an account the firm must collect name, date of birth, address and an identification number, and verify identity.");
F(5,4,"Person (Uniform Securities Act)","An individual, corporation, partnership, association, trust, government or political subdivision. A minor or a deceased individual is not a person.");
F(5,4,"Issuer and nonissuer transaction","The issuer is the entity that issues the security. A nonissuer transaction is a secondary-market trade where the proceeds do not go to the issuer.");
F(5,4,"Is a gift a sale?","A gift of assessable stock is a sale; a gift of nonassessable stock is not. Bona fide pledges and stock dividends are not sales.");
F(5,4,"Federal covered securities","Securities listed on a national exchange, investment company securities, and Rule 506 private placements. States may require notice filing, not registration.");
F(5,4,"Registration by qualification","Used for intrastate offerings; becomes effective when the Administrator orders it.");
F(5,4,"Who is not an agent?","An individual representing an issuer in exempt securities or exempt transactions, or in offers to employees for a benefit plan with no commission. Clerical staff.");
F(5,4,"Who is not a broker-dealer in a state?","A firm with no place of business in the state whose only clients there are institutions, other broker-dealers, or existing clients temporarily in the state; also agents, issuers and banks.");
F(5,4,"Form U5","Filed within 30 days when an agent or IAR leaves a firm, with the reason for termination.");
F(5,4,"Minimum financial requirements for state advisers (NASAA model rule)","With custody: $35,000 net worth. With discretion but no custody: $10,000 net worth. A bond may substitute where allowed.");
F(5,4,"SEC registration below $100 million: exceptions","Advisers that would have to register in 15 or more states, internet-only advisers, pension consultants to large plans, and advisers to registered investment companies.");
F(5,4,"Form CRS","A short relationship summary for retail investors (2 pages, 4 for dual registrants) delivered before or at the start of the relationship.");
F(5,4,"Hedge clause","Contract language that makes a client think he or she has waived legal rights against the adviser. Prohibited.");
F(5,4,"Agency cross transaction: conditions","Advance written client consent, a written confirmation of each trade, a yearly summary, and the right to revoke at any time.");
F(5,4,"SEC Marketing Rule (Rule 206(4)-1)","Allows testimonials and endorsements with clear disclosure and oversight; performance must show net results and 1-, 5- and 10-year periods; no untrue or unsubstantiated claims.");
F(5,4,"Investment adviser that is a partnership: change in partners","Clients must be told of a change in membership promptly; a change of a minority interest is not an assignment.");
F(5,4,"Do-not-call rules","Calls only between 8 a.m. and 9 p.m. local time of the person called; honor the national and firm do-not-call lists; give name, firm and a phone number.");
F(5,4,"Regulation S-P incident response (2024 amendments)","Firms need a written incident response program and must notify affected individuals of unauthorized access to sensitive information within 30 days.");
F(5,4,"Securities Act of 1933","Regulates new issues: registration statement with the SEC, prospectus delivery, a 20-day cooling-off period.");
F(5,4,"Securities Exchange Act of 1934","Created the SEC; regulates secondary markets, exchanges, broker-dealers, margin (through the Fed) and insider trading.");
F(5,4,"Investment Company Act of 1940","Regulates mutual funds and other investment companies: registration, a board of directors, limits on affiliated dealings.");
F(5,4,"Insider trading penalties","Civil penalty up to three times the profit gained or loss avoided; criminal up to $5 million and 20 years for individuals.");
F(5,4,"Administrator's summary order","A stop or cease and desist order may be issued without a hearing; the person may then ask for a hearing, which must be held within 15 days.");
/* ---- exam-level questions ---- */
Q(5,1,2,"Which of the following are tools of monetary policy? I. Open market operations II. Changing income tax rates III. Changing the discount rate IV. Government spending","I and III",["II and IV","I, II and III","III and IV"],"Taxes and spending are fiscal policy.");
Q(5,1,2,"During the contraction phase of the business cycle, which is MOST likely?","Rising unemployment and falling corporate profits",["Rising inventories sold quickly and rising profits","Rising interest rates from strong loan demand","Rising consumer spending on durable goods"],"Contraction means less output, fewer jobs and lower profits.");
Q(5,1,2,"Which of these is a coincident economic indicator?","Industrial production",["Building permits","The average prime rate","Stock prices"],"Coincident indicators move with the economy. Permits and stock prices lead; the prime rate lags.");
Q(5,1,2,"The Federal Reserve raises the discount rate. The most likely effect is","higher short-term interest rates and slower lending",["a larger money supply", "lower Treasury bill yields and faster bank lending", "higher bond prices"],"Raising the cost of borrowing tightens credit.");
Q(5,1,3,"A company has net income of $8 million, pays $1 million of preferred dividends and has 3.5 million common shares. EPS is","$2.00",["$2.29","$2.57","$0.50"],"($8M − $1M) ÷ 3.5M = $2.00. Preferred dividends come off before common earnings.");
Q(5,1,3,"A company has total assets of $50 million, liabilities of $30 million, $5 million of preferred stock and 3 million common shares. Book value per common share is","$5.00",["$6.67","$16.67","$8.33"],"($50M − $30M − $5M) ÷ 3M = $5.00.");
Q(5,1,2,"Which section of the statement of cash flows shows money paid out as dividends?","Financing activities",["Operating activities","Investing activities","The income statement"],"Dividends, borrowing and repaying debt, issuing and buying back stock are financing.");
Q(5,1,2,"A U.S. investor owns shares of a German company. The euro falls against the dollar. Ignoring the share price, the investment is worth","less in dollars",["more in dollars","the same in dollars","more only if the company exports to the U.S."],"Currency risk: a weaker foreign currency buys fewer dollars.");
Q(5,1,2,"An analyst says a portfolio has a high correlation with the S&P 500 but a low beta. This means the portfolio","moves in the same direction as the index but with smaller swings",["moves opposite to the index, with much bigger swings than the market", "has no systematic risk", "outperformed the index"],"Correlation is direction; beta is size of the move relative to the market.");
Q(5,1,3,"Two portfolios returned 12% with standard deviations of 10% and 15%. The risk-free rate is 2%. Which has the better risk-adjusted return?","The one with 10% standard deviation, Sharpe ratio 1.0",["The one with 15% standard deviation, Sharpe ratio 0.67","They are equal because returns are equal","It cannot be told without beta"],"(12 − 2) ÷ 10 = 1.0 against (12 − 2) ÷ 15 = 0.67.");
Q(5,1,2,"Which risk is LEAST reduced by holding bonds of many different issuers?","Interest rate risk",["Default risk","Business risk of one issuer","Call risk of one issue"],"Rising rates lower the prices of nearly all bonds; it is systematic.");
Q(5,1,2,"A company's quick ratio is much lower than its current ratio. This tells you the company","holds a large inventory",["has too much cash","has little long-term debt","is very profitable"],"The only difference between the two ratios is inventory.");
Q(5,1,1,"Which document must a public company's auditors examine?","The financial statements in the annual report (10-K)",["The quarterly 10-Q", "Every Form 8-K", "The proxy statement sent before the annual meeting"],"10-K statements are audited; 10-Q statements are reviewed, not audited.");
Q(5,1,2,"Opportunity cost for an investor who keeps $100,000 in a 0.5% savings account instead of a 4% Treasury bill is about","$3,500 a year",["$500 a year","$4,000 a year","nothing, because the savings account is insured"],"The return given up: 4% − 0.5% on $100,000.");
Q(5,1,2,"Sovereign debt risk is MOST closely tied to","a government's ability and willingness to repay",["a company's earnings", "the stock market's volatility in that country", "the issuer's call provisions"],"Political and economic conditions drive it, along with currency risk.");
Q(5,2,2,"All of the following are true of Treasury STRIPS EXCEPT","they pay interest every six months",["they are sold at a discount","the investor owes tax each year on accreted interest","they have no reinvestment risk"],"STRIPS are zero-coupon: no periodic interest.");
Q(5,2,2,"Which mortgage-backed security carries the direct full faith and credit of the U.S. government?","GNMA",["FNMA","FHLMC","A private-label CMO"],"Ginnie Mae is a government agency.");
Q(5,2,2,"Interest rates fall sharply. A holder of mortgage-backed securities is MOST exposed to","prepayment risk",["extension risk","inflation risk","currency risk"],"Homeowners refinance, returning principal early to be reinvested at lower rates.");
Q(5,2,2,"Which corporate bond is backed only by the issuer's general credit?","A debenture",["A mortgage bond","An equipment trust certificate","A collateral trust bond"],"Debentures are unsecured.");
Q(5,2,3,"A bond with a 6% coupon is callable in 5 years and matures in 20. It trades at 110. Which yield is lowest?","Yield to call",["Nominal yield","Current yield","Yield to maturity"],"At a premium, the yield to the earliest redemption date is lowest.");
Q(5,2,2,"Which is true of a money market mutual fund?","It is not FDIC insured, though it seeks a stable $1 share price",["It guarantees a $1 share price", "It invests mainly in long-term bonds and is insured by the FDIC", "It is a bank deposit"],"It is a security, with no deposit insurance.");
Q(5,2,2,"A company does a 2-for-1 stock split. An investor with 100 shares at $80 now has","200 shares at $40",["200 shares at $80","100 shares at $40","100 shares at $160"],"Value stays $8,000; nothing is taxable.");
Q(5,2,2,"Which statement about rights and warrants is true?","Rights are short-term and priced below market; warrants are long-term and priced above market when issued",["Both are issued only to bondholders, and both must be exercised within 30 days of being issued", "Rights never trade", "Warrants give voting rights"],"Rights let existing holders keep their share of the company.");
Q(5,2,2,"The separate account of a variable annuity earns 7% while the AIR is 5%. The next payment will","increase",["decrease","stay the same","stop"],"Returns above the AIR increase the payment; below it, decrease.");
Q(5,2,2,"A client wants to swap an old variable annuity for a new one without paying tax. This is possible under","Section 1035",["Section 529","Rule 144","Regulation T"],"Suitability still matters: a new surrender period and fees may make the swap bad for the client.");
Q(5,2,2,"A beneficiary inherits a nonqualified annuity worth $150,000 with $90,000 of premiums. Tax on the gain is","ordinary income on $60,000",["none, because of the step-up in basis","long-term capital gain on $60,000","ordinary income on $150,000"],"Annuities get no step-up; the deferred gain is taxed as ordinary income.");
Q(5,2,2,"An investor expects a stock to move sharply but does not know which way. Which strategy fits?","Buying a straddle",["Writing a covered call","Buying a protective put only","Selling a straddle"],"A long call plus a long put at the same strike gains from a big move either way.");
Q(5,2,2,"A wheat farmer worried that prices will fall before harvest should","sell wheat futures",["buy wheat futures","buy wheat calls","do nothing; futures cannot hedge"],"A short hedge locks in the selling price.");
Q(5,2,3,"A closed-end fund has a NAV of $25 and trades at a 10% premium. Its market price is","$27.50",["$22.50","$25.00","$25.10"],"$25 × 1.10.");
Q(5,2,2,"Which pooled investment is most likely to have redemption limits and a lock-up period?","A hedge fund",["An index mutual fund","An ETF","A money market fund"],"Private funds often allow redemptions only quarterly or yearly after a lock-up.");
Q(5,2,2,"A non-traded REIT differs from a listed REIT mainly in","liquidity: shares are hard to sell before a liquidity event",["tax treatment", "the 90% distribution rule, which applies only to listed REITs", "what assets it may own"],"Non-traded REITs often carry high fees and limited redemption programs.");
Q(5,2,2,"Which is a risk of a structured note that a Treasury note does not have?","The issuer's credit risk",["Interest rate risk on the note", "Inflation risk", "Market risk"],"The note is a promise of the issuing bank.");
Q(5,2,2,"An investor buys a 2x leveraged S&P 500 ETF to hold for ten years. The main concern is","daily resetting makes long-term results drift from twice the index",["it cannot be sold during the trading day, only at the close", "it pays no dividends", "it is not registered"],"Leveraged and inverse funds are designed for short holding periods.");
Q(5,2,2,"Which life insurance policy lets the owner change premium payments and the death benefit, and invest the cash value in subaccounts?","Variable universal life",["Whole life", "Term life", "Universal life (fixed)"],"Universal gives flexibility; variable adds subaccounts and makes it a security.");
Q(5,2,2,"Which of these is NOT a security?","A whole life insurance policy",["A variable annuity","A variable life policy","An interest in an oil and gas program"],"Fixed insurance products are not securities.");
Q(5,2,2,"Gold held in a portfolio is MOST often used as","a hedge against inflation and currency weakness",["a source of steady income", "a low-volatility substitute for high-grade bonds", "a way to lower taxes"],"Gold pays no income and can be volatile.");
Q(5,2,2,"Which is true of an index mutual fund compared with an actively managed fund in the same category?","It usually has lower expenses and lower turnover",["It always outperforms", "It has no market risk", "It cannot be held in an IRA or a 401(k) plan"],"Lower turnover also tends to mean fewer capital gain distributions.");
Q(5,2,2,"An investor buys shares the day before a mutual fund pays a large capital gain distribution. The result is","an immediate tax bill on the distribution with no gain in value",["a bargain price", "a tax-free return of capital that lowers the share basis", "a higher NAV the next day"],"Buying the dividend: NAV drops by the distribution, which is taxable.");
Q(5,2,3,"A $1,000 convertible bond is convertible at $50. The stock is at $45 and the bond is at $1,000. The bond trades","above parity, at a premium to conversion value",["below parity", "at parity", "at a discount to par and below its conversion value"],"Parity = 20 × $45 = $900; the bond at $1,000 is above it.");
Q(5,2,2,"Which share class is usually best for an investor who will hold a fund only two or three years and invest a small amount?","Class C",["Class A","Class B","Class R"],"No front load; the higher yearly fee costs less over a short period. Over long periods Class A usually wins.");
Q(5,2,2,"Who receives the proceeds in a secondary offering?","The selling shareholders",["The issuing company", "The issuing company itself", "The exchange"],"In a primary offering, the issuer receives the money.");
Q(5,3,2,"A client, 45, has an emergency fund, maxes her 401(k) and wants to save for retirement in a taxable account with minimal taxes. The MOST suitable choice is","a broad-market index fund",["a high-turnover sector fund","a high-yield corporate bond fund","a REIT fund"],"Low turnover and qualified dividends keep taxes down; taxable bonds and REITs suit tax-deferred accounts.");
Q(5,3,2,"A 72-year-old widow needs income, has little other money and dislikes risk. Which is LEAST suitable?","A long-term growth fund of small companies",["Short-term Treasury notes", "An investment-grade bond fund for income", "Certificates of deposit"],"She needs safety and income, not volatility.");
Q(5,3,2,"A client keeps a losing stock because he paid $60 and wants to 'get back to even'. This is an example of","anchoring and loss aversion",["herd behavior", "overconfidence", "mental accounting and herding"],"The purchase price is irrelevant to the decision to hold.");
Q(5,3,2,"An investor in the 35% bracket asks where to hold a high-yield corporate bond fund and a stock index fund. Generally","the bond fund in the IRA and the index fund in the taxable account",["the index fund in the IRA and the bond fund in the taxable account","both in the taxable account","both in the IRA"],"Asset location: tax-inefficient income in tax-deferred accounts.");
Q(5,3,2,"Which statement about Modern Portfolio Theory is true?","Adding a volatile asset can lower portfolio risk if its correlation with the rest is low",["Each security should be judged on its own risk alone", "Diversification removes systematic risk", "Investors should hold only the single highest-returning asset, whatever its risk or correlation"],"Correlation, not standalone risk, drives diversification.");
Q(5,3,2,"A client believes the strong form of the efficient market hypothesis. The client should expect that","no one can consistently beat the market, even with inside information",["fundamental analysis works, but technical analysis can never add value", "insiders always beat the market", "small-company stocks always outperform"],"All information is already in the price.");
Q(5,3,2,"A manager moves money from technology to utilities and consumer staples as a recession approaches. This is","sector rotation",["strategic asset allocation","indexing","dollar-cost averaging"],"Defensive sectors hold up better in contractions.");
Q(5,3,2,"Which is a characteristic of tactical asset allocation?","Short-term departures from the long-term mix to exploit expected market moves",["Never changing the mix", "Rebalancing the portfolio back to its long-term target only once a decade", "Holding only index funds"],"It is an active approach layered on a strategic target.");
Q(5,3,2,"A value manager would MOST likely buy a stock with","a low P/E ratio and a high dividend yield",["a high P/E ratio and no dividend", "rapid sales growth and no earnings yet", "the best recent price momentum"],"Value looks for underpriced companies; growth pays up for fast growth.");
Q(5,3,3,"A client in the 24% bracket sells stock held 9 months at a $5,000 gain. The federal tax on the gain is","$1,200",["$750","$0","$1,000"],"Held one year or less: short-term, taxed as ordinary income at 24%.");
Q(5,3,2,"An investor gives stock with a basis of $10,000 and a value of $40,000 to her son. Later he sells it for $45,000. His gain is","$35,000",["$5,000","$45,000","$0"],"Gifted property keeps the donor's basis (when sold at a gain).");
Q(5,3,2,"A client turns 73 this year. Which accounts require a minimum distribution for this year? I. Traditional IRA II. Roth IRA III. SEP IRA IV. Roth 401(k)","I and III",["I, II and III","I only","I, III and IV"],"Roth IRAs have no RMDs for the owner, and Roth 401(k)s have none since 2024.");
Q(5,3,2,"A 40-year-old non-spouse beneficiary inherited a traditional IRA in 2025 from her father, who had begun RMDs. She must generally","take yearly RMDs and empty the account by the end of the tenth year",["take it all within 60 days", "roll it into her own IRA", "take nothing until she reaches age 73, and then begin yearly RMDs for life"],"The 10-year rule; yearly RMDs apply because the owner had begun them.");
Q(5,3,2,"A client completes an indirect IRA rollover on day 75. The result is","the distribution is taxable and may face the 10% penalty",["no tax, because the money went into an IRA in the end", "only a 6% excise tax", "a second rollover is allowed"],"Indirect rollovers must be finished within 60 days.");
Q(5,3,2,"A participant takes a $50,000 lump sum from a 401(k) paid to herself, planning to roll it over. The plan must withhold","$10,000",["$0","$5,000","$12,500"],"20% mandatory withholding; a direct rollover avoids it.");
Q(5,3,2,"A self-employed dentist with no employees wants the highest contribution with a Roth option. The best fit is","a solo 401(k)",["a SIMPLE IRA","a Coverdell ESA","a 457 plan"],"Solo 401(k)s allow employee deferrals (Roth or traditional) plus employer contributions.");
Q(5,3,2,"Which is true of a 457 plan for state employees?","Withdrawals after leaving the employer have no 10% early withdrawal penalty",["Only public school teachers may join", "Contributions are made after tax only, so withdrawals are tax-free", "It must be covered by ERISA"],"Government plans are not under ERISA, and 457(b) has no 10% penalty.");
Q(5,3,2,"Which feature belongs to a nonqualified deferred compensation plan?","It may cover only selected executives",["Contributions are deductible by the employer when made","Assets are protected from the employer's creditors","It must cover all employees"],"The employer deducts only when it pays the benefit, and the promise is unsecured.");
Q(5,3,2,"An ERISA plan sponsor picks a target-date fund for employees who make no choice. That fund is the plan's","qualified default investment alternative",["investment policy statement default", "prohibited transaction", "safe harbor rule 404(a)"],"A QDIA gives the fiduciary relief for defaulted money.");
Q(5,3,2,"A plan trustee buys land owned by the plan sponsor's chief executive for the plan. This is","a prohibited transaction",["allowed if the price is fair","allowed with participant consent","a QDIA"],"Dealing with a party in interest is prohibited under ERISA.");
Q(5,3,2,"A grandmother wants to give $95,000 to a grandson's 529 plan this year without using any lifetime exemption. In 2026 she may","elect to spread it over five years at $19,000 a year",["only give $19,000", "give it only through an UTMA account in her name", "give it only to a Coverdell"],"Five-year averaging: 5 × $19,000 = $95,000.");
Q(5,3,2,"A parent wants to save for a child's private high school tuition in a tax-advantaged account. Which can be used? I. 529 plan II. Coverdell ESA III. UTMA","I, II and III",["I only","II only","I and II only"],"529s can pay K-12 tuition (the yearly limit rose from $10,000 to $20,000 in 2026); Coverdell covers K-12; an UTMA can be spent for the child's benefit.");
Q(5,3,2,"Two brothers own a rental property as JTWROS. One dies leaving a will that gives everything to his daughter. The property goes to","the surviving brother",["the daughter","the estate","the daughter and brother equally"],"Survivorship overrides the will for JTWROS property.");
Q(5,3,2,"A married couple in a community property state buys stock with income earned during the marriage. Generally the stock is","owned equally by both spouses",["owned by the spouse who earned the money","owned by the spouse named first","owned by the children"],"Community property: each spouse owns half.");
Q(5,3,2,"A client with a large estate wants to remove a life insurance policy from his taxable estate. A common tool is","an irrevocable life insurance trust",["a revocable living trust", "a TOD registration", "a joint account with his adult son"],"Assets in a revocable trust stay in the estate.");
Q(5,3,2,"In a divorce, a 401(k) is split with a QDRO. The ex-spouse, age 45, takes a cash distribution. Result?","Taxable income but no 10% early withdrawal penalty",["Tax-free", "Taxable income plus the 10% early withdrawal penalty", "Not allowed under ERISA"],"Distributions to an alternate payee under a QDRO avoid the 10% penalty.");
Q(5,3,2,"A buy limit order at $40 is entered when the stock is at $42. The order","will fill only at $40 or lower",["fills at once at $42","becomes a market order at $40","fills only at $40 or higher"],"Buy limits sit below the market; they guarantee price, not execution.");
Q(5,3,2,"A short seller wants protection against a sharp rise in the stock. The order to use is","a buy stop above the market",["a sell stop below the market","a buy limit below the market","a sell limit above the market"],"A buy stop caps the loss on a short position.");
Q(5,3,2,"The maximum potential loss on a short sale of stock is","unlimited",["the sale proceeds","the margin deposit","the stock's value at the time of the sale"],"A stock's price can rise without limit.");
Q(5,3,2,"Which describes a cash account?","Securities must be paid for in full; no borrowing or short selling",["Purchases may be made on credit", "The firm may lend the securities and the client may borrow on them", "It requires a margin agreement"],"Short sales and borrowing need a margin account.");
Q(5,3,2,"A firm that routes customer orders to a market maker in return for payment must","disclose its payment for order flow and still seek best execution",["refuse the payment", "give the payment to the SEC", "stop executing customer orders until the SEC approves the payments"],"The conflict is disclosed; best execution still applies.");
Q(5,3,2,"Which role is played by a clearing broker-dealer?","Settles trades and holds customer accounts for introducing firms",["Writes the investment policy", "Sets exchange listing standards", "Acts as the client's fiduciary investment adviser on every trade"],"Introducing firms deal with clients; clearing firms process and hold.");
Q(5,3,3,"A client invested $10,000, added $10,000 after one year when the fund had fallen 20%, and the fund then rose 25%. Which is true?","The time-weighted return is 0%; the dollar-weighted return is positive",["Both are 0%", "Both are positive", "The time-weighted return is positive; the dollar-weighted is zero"],"(0.80 × 1.25) − 1 = 0% for the fund; the investor's added money earned 25%.");
Q(5,3,3,"A municipal bond fund yields 3.2%. For an investor in the 32% bracket, the taxable equivalent is about","4.71%",["2.18%","4.22%","3.52%"],"3.2% ÷ 0.68 = 4.71%.");
Q(5,3,2,"Which benchmark is MOST appropriate for a portfolio of U.S. small-company stocks?","Russell 2000",["S&P 500","Dow Jones Industrial Average","Bloomberg U.S. Aggregate Bond Index"],"Match the benchmark to the portfolio's style and size.");
Q(5,3,2,"An adviser's client data form should include all of the following EXCEPT","the client's preferred political party",["investment objectives and time horizon", "risk tolerance", "tax bracket"],"Personal values that matter to investing (such as ESG wishes) belong, but not unrelated personal data.");
Q(5,3,2,"A client says she wants growth but panics and sells whenever the market falls 10%. The adviser should","treat her real risk tolerance as low and discuss it",["ignore the behavior and buy aggressive growth funds anyway", "stop advising her", "recommend leveraged ETFs"],"Behavior reveals risk tolerance more reliably than stated goals.");
Q(5,3,2,"A sole proprietor's business is sued and loses. Which is at risk?","The owner's personal assets",["Only the business bank account","Nothing, because the business is separate","Only the business equipment"],"There is no separate entity and no limited liability.");
Q(5,3,2,"Which entity can have more than 100 owners, foreign owners and several classes of stock?","A C corporation",["An S corporation","A sole proprietorship","A general partnership with limited liability"],"S corporations are limited to 100 shareholders, one class of stock and no nonresident aliens.");
Q(5,3,2,"Income from a limited partnership is reported to partners on","Schedule K-1",["Form 1099-DIV","Form W-2","Form 1099-B"],"Partnerships pass income and losses through on K-1s.");
Q(5,3,2,"A charity's endowment wants to follow the Uniform Prudent Investor Act. Which is consistent with it?","Hiring an outside investment manager and monitoring the manager",["Banning all stocks as speculative", "Judging each holding only by its own risk, not the portfolio's", "Never diversifying to avoid fees"],"UPIA allows delegation and judges the portfolio as a whole.");
Q(5,4,2,"Under the Uniform Securities Act, which of the following is a person? I. A corporation II. A minor III. A government IV. A deceased individual","I and III",["Only a certified public accountant who also sells insurance products for commission", "II and IV", "I, III and IV"],"Minors, deceased people and the legally incompetent are not persons.");
Q(5,4,2,"Which is NOT a sale under the Uniform Securities Act?","A bona fide pledge of stock as collateral for a loan",["A gift of assessable stock", "An offer to buy a bond with a bonus share of stock", "A transaction for value"],"Pledges, gifts of nonassessable stock and stock dividends are not sales.");
Q(5,4,2,"An agent is employed by an issuer to sell the issuer's U.S. Treasury notes to the public. Is the person an agent under the Act?","No, because the issuer's securities are exempt",["Yes, every seller is an agent", "Yes, unless the agent is paid a salary only", "Only in the agent's home state"],"Representing an issuer in exempt securities is excluded from the definition.");
Q(5,4,2,"A broker-dealer with no office in State X sells to a client who lives in State Y and is on vacation in State X for two weeks. In State X the firm","does not have to register",["must register","must notice file","must register its agents only"],"Existing clients temporarily in the state are an exclusion.");
Q(5,4,2,"Which security is a federal covered security?","Common stock listed on the New York Stock Exchange",["A stock sold in an intrastate offering under Rule 147", "A penny stock traded over the counter", "A security in a Rule 504 offering"],"Exchange-listed securities, investment company securities and Rule 506 offerings are federal covered.");
Q(5,4,2,"A company issuing stock only in its home state, with no SEC registration, would register by","qualification",["coordination","notice filing","exemption under the 1934 Act"],"Qualification is the method when no federal registration exists.");
Q(5,4,2,"Which is an exempt transaction under the Uniform Securities Act?","A sale to a bank or insurance company",["A sale of a penny stock to a retail client","An issuer's IPO to the public","A solicited trade in an unregistered security"],"Transactions with institutional buyers are exempt.");
Q(5,4,2,"Which securities are exempt from state registration? I. Securities of a U.S. bank II. Securities of a foreign government with diplomatic relations with the U.S. III. Securities of a nonprofit hospital IV. Securities of a public utility holding company not regulated as a utility","I, II and III",["I and II only","II, III and IV","I, II, III and IV"],"Bank, foreign government (recognized) and nonprofit issues are exempt.");
Q(5,4,2,"An Administrator learns that an agent's application omitted a felony conviction from 8 years ago. The Administrator may","deny or revoke the registration after notice and an opportunity for a hearing",["fine the agent $1 million", "imprison the agent", "take no action at all, because 5 years have passed since the conviction"],"A false application and a felony within 10 years are grounds.");
Q(5,4,2,"An Administrator issues a summary cease and desist order. The person receiving it may request a hearing, which must be held within","15 days",["30 days","60 days","10 business days"],"The order stays in effect until the hearing.");
Q(5,4,2,"A registered agent withdraws her registration. The Administrator may still start a revocation proceeding for","one year after the withdrawal",["30 days", "five years", "no time at all after the withdrawal"],"Withdrawal is effective after 30 days, but jurisdiction lasts one year.");
Q(5,4,2,"A client who bought an unregistered nonexempt security learns of it and receives a written rescission offer. If the client does not accept within 30 days, the client","loses the right to sue under the Act",["can still sue for three years after the sale", "must accept the offer", "receives triple damages"],"An unaccepted rescission offer ends the civil claim.");
Q(5,4,2,"Which person must register as an investment adviser in a state?","A sole practitioner with an office in the state managing money for 12 individuals for a fee",["A bank trust department", "A CPA who gives incidental advice", "A newspaper columnist writing about stocks for a paper sold to the general public"],"Office in the state, retail clients, fee for advice.");
Q(5,4,2,"An adviser with $70 million under management and an office only in State A, with no other exemptions, registers with","State A",["the SEC","the SEC and State A","FINRA"],"Under $100 million generally means state registration.");
Q(5,4,2,"An adviser with $80 million under management must register in 16 states. The adviser","may register with the SEC instead",["must register in all 16 states only","may not do business","must register with FINRA"],"The multistate exemption: 15 or more states.");
Q(5,4,2,"Which statement about IAR registration is true?","An IAR of a federal covered adviser registers only in states where he or she has a place of business",["An IAR of a federal covered adviser registers only with the SEC and never with any state at all", "Clerical staff must register", "An IAR never needs to pass an exam"],"The SEC does not register individuals.");
Q(5,4,2,"A state-registered adviser has custody of client funds. Under NASAA model rules the adviser must maintain a minimum net worth of","$35,000",["$10,000","$25,000","$100,000"],"With discretion but no custody, $10,000.");
Q(5,4,2,"Form ADV Part 2B gives clients information about","the individuals who advise them: education, experience and disciplinary history",["the firm's audited financial statements and balance sheet for the last three years", "the firm's IRS filings", "the custodian's fees"],"2A is about the firm; 2B is about the supervised persons.");
Q(5,4,2,"When must Form CRS be delivered to a new retail advisory client?","Before or at the time the advisory agreement is entered into",["Within 30 days after the first trade is placed in the account", "Only on request", "Once a year only"],"It must also be updated within 30 days of a material change.");
Q(5,4,2,"Which item is required in an advisory contract under state rules? I. The fee and formula II. Whether the adviser has discretion III. That the contract cannot be assigned without consent IV. The client's waiver of any claims","I, II and III",["I and II only","II, III and IV","I, II, III and IV"],"A waiver (hedge clause) is prohibited.");
Q(5,4,2,"An adviser's contract states, 'The adviser is not liable for any losses, however caused.' This is","a prohibited hedge clause",["acceptable if the client signs","required by the SEC","acceptable for wealthy clients"],"Clients cannot be led to waive rights under securities law.");
Q(5,4,2,"Which compensation arrangement for a retail client of a state-registered adviser is generally allowed?","A fee of 1% of assets under management",["20% of the client's capital gains for a client with $500,000 managed","A share of profits with no sharing of losses","A guaranteed minimum return"],"Asset-based fees are not performance fees; performance fees need a qualified client.");
Q(5,4,2,"An adviser uses client commissions to buy research software that also runs the adviser's accounting. Under Section 28(e)","only the research portion may be paid with soft dollars; the rest must be paid in cash",["the whole cost may be paid with soft dollars, as long as the arrangement is disclosed", "none may be paid with soft dollars", "the client must pay the rest"],"Mixed-use items must be allocated, with records.");
Q(5,4,2,"An adviser is given power of attorney to write checks from a client's account to pay the client's bills. The adviser","has custody",["has discretion only","has neither custody nor discretion","is an agent of the client's bank"],"Authority to withdraw funds is custody.");
Q(5,4,2,"Under the SEC custody rule, client funds and securities must be held by","a qualified custodian, such as a bank or registered broker-dealer",["the adviser's own office safe or its operating bank account", "the client's attorney", "any CPA firm"],"With account statements sent at least quarterly.");
Q(5,4,2,"An adviser buys stock for its own account just before placing a large order for its clients. This is","front running, a prohibited practice",["allowed if disclosed in Form ADV","best execution","an agency cross"],"The adviser profits at the clients' expense.");
Q(5,4,2,"An adviser plans to buy 50,000 shares for many client accounts and cannot fill the whole order at one price. A fair way to allocate is","pro rata at the average price",["the best prices to the adviser's family accounts","the best prices to the largest fee-payers","first come first served by account number"],"Allocation must be fair and consistent with written policies.");
Q(5,4,2,"Which is an unethical business practice for an investment adviser?","Telling a client that the adviser's fees are lower than they are",["Charging a fee that is reasonable and fully disclosed in advance", "Recommending a fund the adviser researched", "Disclosing a conflict of interest in writing"],"Misrepresenting fees, qualifications or services is prohibited.");
Q(5,4,2,"Which is TRUE about an IAR's personal trading?","Access persons must report holdings and quarterly transactions under the firm's code of ethics",["IARs may not own any securities", "IARs may trade ahead of clients if the amount is small and the trade is reported later", "Personal trades never need reporting"],"Holdings within 10 days of becoming an access person and yearly; transactions within 30 days after each quarter.");
Q(5,4,2,"An IAR learns from a client, who is a company director, that the company will be acquired. The IAR buys the stock. This is","insider trading",["legal because the client told him","legal if he holds the stock more than a year","a soft-dollar arrangement"],"Trading on material nonpublic information is prohibited, and so is passing it on.");
Q(5,4,2,"An adviser to a state pension fund donates $1,000 to the governor's campaign; the governor appoints the fund's board. The adviser","may not receive paid advisory business from the fund for two years",["is fine, because the amount is under $5,000 per election and per candidate", "must only disclose it", "must refund the governor"],"The pay-to-play rule. The de minimis amounts are $350 (if the contributor can vote for the official) or $150.");
Q(5,4,2,"An IAR suspects that a 78-year-old client is being financially exploited by a caregiver. Under the NASAA model act the IAR","may notify the state securities regulator and adult protective services and may delay a suspicious disbursement",["must close the account", "must call the police and nobody else", "may not act at all without the caregiver's written consent, even if exploitation is suspected and money is leaving"],"Good-faith reporting gives immunity; delays are limited in time.");
Q(5,4,2,"Under Regulation S-P, an adviser must give clients a privacy notice","when the relationship begins and yearly, unless an exception applies",["only when asked", "only when information is shared with affiliates, never with others", "every quarter"],"Clients may opt out of sharing nonpublic personal information with nonaffiliated third parties.");
Q(5,4,2,"An adviser's business continuity plan should address all of the following EXCEPT","guaranteeing clients will have no losses during a disaster",["how clients can reach the firm", "backup of books and records", "who takes over the clients and accounts if a key person dies"],"No plan can guarantee investment results.");
Q(5,4,2,"An IAR posts on a public social media page, 'Our clients never lose money.' This is","a misleading communication and a prohibited guarantee",["acceptable if true for most clients","acceptable on social media","acceptable if the post is deleted within 24 hours"],"Social media posts are advertising and fall under antifraud rules.");
Q(5,4,2,"Under the SEC Marketing Rule, an adviser that shows gross performance in an advertisement must also show","net performance with equal prominence",["only the best year", "the client's name", "performance of other advisers' funds"],"Net-of-fee figures for 1, 5 and 10 years are required.");
Q(5,4,2,"Which call to a residential prospect is permitted under the Telephone Consumer Protection Act?","A call at 8:30 p.m. local time to someone not on the do-not-call list",["A call at 7:30 a.m. local time","A call to someone on the national do-not-call list with no relationship","A call at 9:30 p.m. local time"],"Calls only between 8 a.m. and 9 p.m. in the recipient's time zone.");
Q(5,4,2,"Which law created the SEC?","The Securities Exchange Act of 1934",["The Securities Act of 1933","The Investment Company Act of 1940","The Uniform Securities Act"],"The 1933 Act regulates new issues; the 1934 Act created the SEC and regulates trading.");
Q(5,4,2,"An agent transfers from Firm A to Firm B. While the transfer is pending, the agent","may not do business for Firm B until registered with it",["may work for both firms", "may sell only exempt securities for Firm B until then", "may sell for Firm B if the client agrees"],"Registration is tied to the employing firm.");
Q(5,4,2,"Which activity is NOT selling away?","Recommending a mutual fund the firm offers",["Selling a client a private note the firm does not know about","Arranging a real estate investment for a client outside the firm without approval","Selling an unapproved private placement for a commission paid by the issuer"],"Selling away is outside the firm, without written approval.");
Q(5,4,2,"An IAR borrows $25,000 from a long-time client who is a retired engineer, with a written note. This is","prohibited, because the client is not a broker-dealer, an affiliate or a lending institution",["allowed with a written note", "allowed if repaid within a year", "allowed, as long as the client is an accredited investor and the loan is written down"],"The exception covers only those in the business of lending, broker-dealers or affiliates.");
Q(5,4,3,"An adviser with discretion places 40 trades a month in a retired client's account with income objectives, earning commissions through an affiliate. Which violation is MOST likely?","Excessive trading (churning)",["Front running", "Selling away", "A hedge clause in the contract"],"Trading frequency that serves the adviser, not the client's objectives.");
Q(5,4,2,"Which is TRUE of the Administrator's investigative power?","It may subpoena witnesses and records and may act in or outside the state",["It must obtain a court order to investigate", "It may only investigate registered persons", "It may arrest a person who refuses a subpoena and hold that person"],"If someone refuses a subpoena, the Administrator asks a court to compel.");
Q(5,4,2,"Before an Administrator's final order denying a registration, the applicant is entitled to","prior notice, an opportunity for a hearing, and written findings of fact and conclusions of law",["a jury trial", "a refund of fees only", "nothing at all; the order is final as soon as the Administrator signs it"],"Summary orders may come first, but final orders need these protections.");
Q(5,4,2,"A client sues under the Uniform Securities Act and wins. The client may recover","the purchase price plus interest, court costs and attorney's fees, less income received",["triple damages", "only the loss, without interest, court costs or attorney's fees of any kind", "only attorney's fees"],"The Act sets out these civil remedies.");
Q(5,4,2,"An unregistered person sells a nonexempt security in a state. Criminal liability requires that the violation was","willful",["accidental","reported by the client","larger than $10,000"],"Criminal penalties apply only to willful violations.");
Q(5,4,2,"Which person is an investment adviser representative of a state-registered adviser? I. A partner who manages client accounts II. A receptionist III. An employee who recommends securities to clients IV. A salesperson who solicits advisory clients","I, III and IV",["I and III only","II and IV","I, II, III and IV"],"Clerical and administrative staff are not IARs.");
Q(5,4,2,"An exempt reporting adviser advises only venture capital funds. It must","file parts of Form ADV with the SEC but does not register",["register fully with the SEC like any other adviser", "register in every state", "file nothing at all"],"ERAs report; they do not register.");
Q(5,4,2,"How long must an investment adviser keep its books and records, and where for the first part?","Five years, the first two in an appropriate office of the adviser",["Three years, all of them in the adviser's principal office", "Six years, anywhere", "Two years, then destroy"],"Broker-dealer records under the USA are 3 years.");
Q(5,4,2,"Which is a requirement of a customer identification program?","Verifying the identity of each new customer, including name, date of birth, address and ID number",["Collecting the customer's tax returns", "Filing a currency transaction report with FinCEN for every new account that is opened", "Obtaining a credit report for every customer"],"Part of anti-money laundering rules under the USA PATRIOT Act.");
Q(5,4,2,"A broker-dealer agent receives $9,500 in cash from a customer on Monday and $9,000 on Tuesday. The firm","should consider whether the deposits are structured and file a SAR if suspicious, and must file a CTR when cash in one day exceeds $10,000",["need do nothing", "must file a CTR for each deposit, since any cash deposit at all triggers a report, but never needs to consider a SAR", "must return the cash"],"CTR: over $10,000 in a day; SAR: suspicious activity of $5,000 or more.");
